/* Question bank, part A: stimuli + Lessons 0–8.
   d: e=easy m=medium h=hard c=challenge · sk: cause|compare|ccot|context|source|claim
   w[] gives a short reason for every option. */
window.STIM = window.STIM || {};
Object.assign(window.STIM, {
  winthrop: { text: '“For we must consider that we shall be as a city upon a hill. The eyes of all people are upon us, so that if we shall deal falsely with our God in this work we have undertaken, and so cause Him to withdraw His present help from us, we shall be made a story and a by-word through the world.”', src: 'John Winthrop, sermon aboard the Arbella, 1630' },
  stampcong: { text: '“That it is inseparably essential to the freedom of a people, and the undoubted right of Englishmen, that no taxes be imposed on them, but with their own consent, given personally, or by their representatives.\n\nThat the people of these colonies are not, and from their local circumstances cannot be, represented in the House of Commons in Great-Britain.”', src: 'Resolutions of the Stamp Act Congress, October 1765' },
  remladies: { text: '“I long to hear that you have declared an independency — and by the way in the new Code of Laws which I suppose it will be necessary for you to make I desire you would Remember the Ladies, and be more generous and favourable to them than your ancestors. Do not put such unlimited power into the hands of the Husbands.”', src: 'Abigail Adams, letter to John Adams, March 31, 1776' },
  paine2: { text: '“Society in every state is a blessing, but government even in its best state is but a necessary evil; in its worst state an intolerable one… Of more worth is one honest man to society and in the sight of God, than all the crowned ruffians that ever lived.”', src: 'Thomas Paine, Common Sense, January 1776' },
  washshays: { text: '“I feel, my dear Genl. Knox, infinitely more than I can express to you, for the disorders which have arisen in these States. Good God! who besides a tory could have foreseen, or a Briton predicted them!… What stronger evidence can be given of the want of energy in our governments than these disorders?”', src: 'George Washington, letter to Henry Knox, December 26, 1786' },
  threefifths: { text: '“Representatives and direct Taxes shall be apportioned among the several States which may be included within this Union, according to their respective Numbers, which shall be determined by adding to the whole Number of free Persons, including those bound to Service for a Term of Years, and excluding Indians not taxed, three fifths of all other Persons.”', src: 'U.S. Constitution, Article I, Section 2 (1787)' },
  fed10: { text: '“Extend the sphere, and you take in a greater variety of parties and interests; you make it less probable that a majority of the whole will have a common motive to invade the rights of other citizens; or if such a common motive exists, it will be more difficult for all who feel it to discover their own strength, and to act in unison with each other.”', src: 'James Madison, Federalist No. 10, 1787' },
  brutus: { text: '“If respect is to be paid to the opinion of the greatest and wisest men who have ever thought or wrote on the science of government, we shall be constrained to conclude, that a free republic cannot succeed over a country of such immense extent, containing such a number of inhabitants, and these encreasing in such rapid progression as that of the whole United States.”', src: '“Brutus,” Essay I, New York Journal, October 1787' },
  farewell: { text: '“Let me now take a more comprehensive view, and warn you in the most solemn manner against the baneful effects of the spirit of party generally… It is our true policy to steer clear of permanent alliances with any portion of the foreign world.”', src: 'George Washington, Farewell Address, 1796' },
  mcculloch: { text: '“Let the end be legitimate, let it be within the scope of the constitution, and all means which are appropriate, which are plainly adapted to that end, which are not prohibited, but consist with the letter and spirit of the constitution, are constitutional.”', src: 'Chief Justice John Marshall, McCulloch v. Maryland, 1819' },
  marbury: { text: '“It is emphatically the province and duty of the judicial department to say what the law is… So if a law be in opposition to the constitution… the court must determine which of these conflicting rules governs the case. This is of the very essence of judicial duty.”', src: 'Chief Justice John Marshall, Marbury v. Madison, 1803' }
});

window.MCQ = window.MCQ || [];
window.MCQ.push(

/* ── L0 ── */
{ id: 'm0001', l: 'l00', d: 'e', sk: 'ccot', q: 'Which statement best describes voting rights in the United States in 1789?', o: ['Most adult white men could vote regardless of property', 'Voting was largely limited to white men who owned property, with rules set by each state', 'The Constitution guaranteed the vote to all male citizens over 21', 'Women could vote in federal but not state elections'], a: 1, x: 'The original Constitution left voter qualifications to the states, and most required property ownership.', w: ['Property requirements weren’t widely dropped until the 1820s–1840s.', 'Correct. States set the rules, and most required property.', 'The Constitution set no voting qualifications at all.', 'Women generally couldn’t vote anywhere (New Jersey was a brief exception).'] },
{ id: 'm0002', l: 'l00', d: 'm', sk: 'ccot', q: 'Which of the following developments came FIRST?', o: ['The 15th Amendment bans racial discrimination in voting', 'Most states drop property requirements for white male voters', 'The 19th Amendment grants women the vote', 'The Voting Rights Act enforces the 15th Amendment'], a: 1, x: 'Property requirements fell in the 1820s–1840s, before the 15th (1870), 19th (1920) and the VRA (1965).', w: ['1870. Later than the property-requirement changes.', 'Correct: 1820s–1840s.', '1920.', '1965.'] },
{ id: 'm0003', l: 'l00', d: 'h', sk: 'context', q: 'A question asks: “The ideas expressed in the excerpt most directly reflect which broader development?” Which strategy best fits this question type?', o: ['Identify the author’s tone and vocabulary', 'Place the source in the larger situation of its time period', 'Compare the source to a later source with similar ideas', 'Find the option that contains the most specific factual detail'], a: 1, x: 'This is a contextualization question: what larger development explains the source?', w: ['Tone can help, but the task is to connect to a broader development.', 'Correct. Contextualization means situating the source.', 'That’s a comparison task.', 'Specific-sounding options are often distractors from the wrong period.'] },

/* ── L1 Colonies ── */
{ id: 'm0101', l: 'l01', d: 'e', sk: 'compare', q: 'Which colonial region was MOST economically stratified?', o: ['New England', 'The Middle Colonies', 'The Southern Colonies', 'All regions were roughly equal'], a: 2, x: 'Plantation agriculture concentrated wealth in a small planter elite, with poor farmers and enslaved people below.', w: ['New England had small family farms and the least stratification.', 'Moderate stratification.', 'Correct.', 'The regions differed sharply.'] },
{ id: 'm0102', l: 'l01', d: 'e', sk: 'compare', q: 'The Middle Colonies were known as the “breadbasket” because they', o: ['grew large quantities of cereal crops such as wheat for export', 'relied on rice and indigo plantations', 'imported most of their food from the West Indies', 'were settled mostly by Puritans who farmed communally'], a: 0, x: 'Fertile soil and a moderate climate let the Middle Colonies grow and export grain and flour.', w: ['Correct.', 'Rice and indigo were Carolina and Georgia crops.', 'They exported food, not imported it.', 'Puritans settled New England.'] },
{ id: 'm0103', l: 'l01', d: 'm', sk: 'cause', q: 'Which factor most directly explains why Chesapeake planters shifted from indentured servants to enslaved Africans in the late 1600s?', o: ['The Navigation Acts banned indentured servitude', 'Fears of unrest among landless former servants after Bacon’s Rebellion', 'Puritan opposition to indentured servitude', 'The end of tobacco cultivation in Virginia'], a: 1, x: 'Bacon’s Rebellion (1676) showed planters the danger of a growing class of poor, armed former servants; enslaved labor was permanent and hereditary.', w: ['The Navigation Acts regulated trade, not labor systems.', 'Correct.', 'Puritans were in New England and had no say over Virginia.', 'Tobacco remained Virginia’s main crop.'] },
{ id: 'm0104', l: 'l01', d: 'm', sk: 'context', s: 'winthrop', q: 'The ideas in the excerpt most directly reflect which goal of New England’s founders?', o: ['Establishing a profitable tobacco colony', 'Creating a model religious community for others to follow', 'Guaranteeing religious toleration for all faiths', 'Building an alliance with Native peoples'], a: 1, x: 'A “city upon a hill” watched by the world is a model Christian commonwealth: the Puritan mission.', w: ['Tobacco was a Chesapeake goal.', 'Correct.', 'Puritans did NOT tolerate dissent (Williams and Hutchinson were banished).', 'Nothing in the excerpt concerns Native alliances.'] },
{ id: 'm0105', l: 'l01', d: 'h', sk: 'claim', s: 'winthrop', q: 'Which of the following would most directly CHALLENGE the idea that New England’s Puritan society lived up to the ideals in the excerpt?', o: ['The founding of Harvard College in 1636', 'The banishment of Roger Williams and Anne Hutchinson for their religious views', 'The growth of shipbuilding and Atlantic trade', 'The establishment of town meetings'], a: 1, x: 'Punishing dissenters shows a gap between the godly-community ideal and its intolerant practice.', w: ['Harvard trained ministers, which fits the religious mission.', 'Correct: intolerance clashes with the “model” ideal.', 'Economic growth doesn’t directly challenge a religious ideal.', 'Town meetings fit the community-centered vision.'] },
{ id: 'm0106', l: 'l01', d: 'm', sk: 'cause', q: 'Under the policy of salutary neglect, colonial legislatures', o: ['lost the power to levy taxes to royal governors', 'gained experience in self-government, including control over taxation', 'were abolished and replaced by Parliamentary appointees', 'were required to send representatives to Parliament'], a: 1, x: 'Loose British enforcement let assemblies run their own affairs and hold the “power of the purse.”', w: ['The opposite. Assemblies often paid governors’ salaries.', 'Correct.', 'Assemblies grew stronger, not weaker.', 'Colonists never sat in Parliament.'] },
{ id: 'm0107', l: 'l01', d: 'h', sk: 'compare', q: 'New England and the Middle Colonies were most similar in that both', o: ['relied primarily on enslaved labor for agriculture', 'had economies based on family farms and Atlantic trade through port cities', 'were the most religiously tolerant regions', 'grew rice and indigo as cash crops'], a: 1, x: 'Both had family farms, mixed economies and busy ports (Boston, New York, Philadelphia).', w: ['Slavery existed in both but was not central to either economy.', 'Correct.', 'New England was the LEAST tolerant region.', 'Rice and indigo were Lower South crops.'] },
{ id: 'm0108', l: 'l01', d: 'h', sk: 'cause', q: 'Which best explains why Britain wanted to limit colonial trade with other nations under mercantilism?', o: ['To protect colonial manufacturers from European competition', 'To ensure that colonial wealth flowed to the mother country and built a favorable balance of trade', 'To reduce the colonies’ dependence on enslaved labor', 'To encourage the colonies to develop their own navy'], a: 1, x: 'Mercantilism aimed to enrich the mother country through exports, raw materials and gold, not to help colonies compete.', w: ['Britain discouraged colonial manufacturing.', 'Correct.', 'Mercantilism had nothing to do with reducing slavery; the slave trade was part of it.', 'Britain wanted colonies dependent on the Royal Navy.'] },
{ id: 'm0109', l: 'l01', d: 'c', sk: 'ccot', q: 'Which of the following colonial developments shows the most direct CONTINUITY with the arguments colonists later made against the Stamp Act?', o: ['The rise of plantation agriculture in the Chesapeake', 'Colonial assemblies’ long practice of controlling local taxation', 'The Navigation Acts’ requirement to ship tobacco to England', 'The Puritans’ belief in predestination'], a: 1, x: 'Colonists argued only their own assemblies could tax them, which is exactly what those assemblies had done for decades under salutary neglect.', w: ['Plantation agriculture is about labor and economy, not taxation rights.', 'Correct.', 'The Navigation Acts regulated trade; colonists mostly accepted trade regulation before 1763.', 'A religious doctrine unrelated to taxation.'] },

/* ── L2 Road to Revolution ── */
{ id: 'm0201', l: 'l02', d: 'e', sk: 'cause', q: 'The French and Indian War began primarily over competing claims to', o: ['the Ohio River Valley', 'the Caribbean sugar islands', 'New Orleans and the mouth of the Mississippi', 'the fishing grounds off Newfoundland'], a: 0, x: 'British colonists and the French both claimed the Ohio Valley; Washington’s 1754 skirmishes there started the war.', w: ['Correct.', 'Fighting happened there, but it wasn’t the North American trigger.', 'New Orleans was French and not in dispute in 1754.', 'Not the cause of the 1754 fighting.'] },
{ id: 'm0202', l: 'l02', d: 'e', sk: 'cause', q: 'Parliament passed the Stamp Act in 1765 mainly to', o: ['punish Boston for destroying tea', 'raise revenue to help pay debts and defense costs after the French and Indian War', 'protect colonial printers from British competition', 'encourage settlement west of the Appalachians'], a: 1, x: 'War debt and the cost of stationing troops drove Britain’s new revenue taxes.', w: ['The Tea Party was 1773, after the Stamp Act.', 'Correct.', 'The tax burdened printers.', 'The Proclamation of 1763 discouraged western settlement.'] },
{ id: 'm0203', l: 'l02', d: 'm', sk: 'source', s: 'stampcong', q: 'The resolutions in the excerpt most directly reject which British argument?', o: ['That the colonies should pay for their own defense', 'That colonists were virtually represented in Parliament', 'That the king had a divine right to rule', 'That colonial trade must pass through England'], a: 1, x: 'The second resolution denies colonists can be represented in the House of Commons, which rejects virtual representation.', w: ['The resolutions focus on consent and representation, not the cost of defense.', 'Correct.', 'Colonists still professed loyalty to the king in 1765.', 'Trade regulation wasn’t the issue here; taxation was.'] },
{ id: 'm0204', l: 'l02', d: 'm', sk: 'context', s: 'stampcong', q: 'The Stamp Act Congress was significant primarily because it', o: ['declared independence from Great Britain', 'was an early example of several colonies coordinating resistance to British policy', 'created the Continental Army', 'ended the policy of salutary neglect'], a: 1, x: 'Nine colonies acting together in 1765 previewed later unity (Committees of Correspondence, the Continental Congresses).', w: ['Independence came in 1776.', 'Correct.', 'The Second Continental Congress created the army in 1775.', 'British policy, not the Congress, ended salutary neglect.'] },
{ id: 'm0205', l: 'l02', d: 'm', sk: 'cause', q: 'Colonists objected to the Tea Act of 1773 even though it lowered the price of tea because', o: ['it raised the tax on tea to record levels', 'buying the tea meant accepting Parliament’s right to tax the colonies', 'it banned colonists from drinking tea', 'it required tea to be taxed by colonial assemblies'], a: 1, x: 'The objection was principle, not price; smuggling merchants also feared the East India Company monopoly.', w: ['The tax stayed the same; the price fell.', 'Correct.', 'No such ban existed.', 'If assemblies had controlled the tax, colonists would have had less to object to.'] },
{ id: 'm0206', l: 'l02', d: 'h', sk: 'cause', q: 'The Coercive (Intolerable) Acts most directly contributed to the coming of the Revolution by', o: ['convincing many colonists outside Massachusetts that their own rights were threatened', 'raising taxes on glass, paint and paper', 'ending the Proclamation Line', 'forcing colonial merchants to buy East India Company tea'], a: 0, x: 'Punishing Boston rallied other colonies, and twelve sent delegates to the First Continental Congress.', w: ['Correct.', 'Those were the Townshend Acts (1767).', 'The Coercive Acts didn’t touch the Proclamation Line.', 'That was the Tea Act.'] },
{ id: 'm0207', l: 'l02', d: 'h', sk: 'compare', q: 'How did the Stamp Act differ from earlier British trade laws such as the Navigation Acts?', o: ['It applied only to New England', 'It was a direct tax intended to raise revenue rather than a regulation of trade', 'It was enforced only by colonial courts', 'It taxed goods exported from the colonies to Britain'], a: 1, x: 'Colonists had long accepted Parliament regulating trade; a direct internal tax for revenue was new.', w: ['It applied to all colonies.', 'Correct.', 'Violators could be tried in vice-admiralty courts.', 'It taxed printed paper used within the colonies.'] },
{ id: 'm0208', l: 'l02', d: 'h', sk: 'claim', q: 'Which piece of evidence would best support the argument that colonial resistance before 1775 aimed to restore the old relationship with Britain rather than to win independence?', o: ['The Boston Massacre', 'The Olive Branch Petition sent by the Second Continental Congress', 'The battles of Lexington and Concord', 'Thomas Paine’s Common Sense'], a: 1, x: 'Even after fighting began, Congress petitioned the king for reconciliation in 1775.', w: ['A violent clash doesn’t show reconciliation aims.', 'Correct.', 'Armed conflict.', 'Paine argued FOR independence.'] },
{ id: 'm0209', l: 'l02', d: 'm', sk: 'source', q: 'Paul Revere’s engraving of the Boston Massacre is best understood as', o: ['an accurate eyewitness record of the event', 'propaganda designed to turn colonists against British soldiers', 'a British government notice warning colonists against rioting', 'a neutral illustration published in a London newspaper'], a: 1, x: 'It shows orderly soldiers firing on peaceful citizens, leaving out the crowd’s provocation. Its purpose was persuasion.', w: ['It distorts the event.', 'Correct.', 'It was made by a Patriot, not the British government.', 'It was a colonial publication with a clear point of view.'] },
{ id: 'm0210', l: 'l02', d: 'c', sk: 'ccot', q: 'Which of the following best describes a CHANGE in colonial resistance between 1765 and 1775?', o: ['Colonists shifted from opposing Parliament’s taxes to questioning British authority itself and organizing intercolonial government', 'Colonists shifted from violent protest to purely peaceful petitions', 'Colonial resistance became less coordinated as each colony acted alone', 'Colonists began demanding seats in Parliament instead of opposing taxation'], a: 0, x: 'By 1774–75 the Continental Congresses acted as an intercolonial government, and fighting had begun. That went far beyond tax protests.', w: ['Correct.', 'The reverse: protest grew more confrontational.', 'Coordination increased (Committees of Correspondence, the Congresses).', 'Colonists generally rejected representation in Parliament as impractical.'] },

/* ── L3 Enlightenment / state constitutions ── */
{ id: 'm0301', l: 'l03', d: 'e', sk: 'context', q: 'John Locke’s idea that people may overthrow a government that violates their natural rights most directly influenced', o: ['the Navigation Acts', 'the Declaration of Independence', 'the Three-Fifths Compromise', 'the Proclamation of 1763'], a: 1, x: 'The Declaration’s argument (rights, consent and the right to alter or abolish government) is Locke’s.', w: ['A mercantilist trade law.', 'Correct.', 'A compromise over representation and slavery.', 'A British policy limiting settlement.'] },
{ id: 'm0302', l: 'l03', d: 'e', sk: 'cause', q: 'Thomas Paine’s Common Sense was influential mainly because it', o: ['was written in plain language that persuaded ordinary colonists to support independence', 'proposed the structure of the Articles of Confederation', 'called for reconciliation with the king', 'was officially adopted by the Continental Congress'], a: 0, x: 'Paine’s accessible attack on monarchy moved public opinion toward independence in 1776.', w: ['Correct.', 'Paine didn’t design the Articles.', 'Paine attacked the king.', 'It was a private pamphlet.'] },
{ id: 'm0303', l: 'l03', d: 'm', sk: 'source', s: 'paine2', q: 'The excerpt most directly reflects which Enlightenment-era belief?', o: ['Monarchy is the most stable form of government', 'Government should be limited, and hereditary rulers have no special claim to power', 'The economy should be controlled through mercantilist policies', 'Religious authorities should guide government'], a: 1, x: 'Calling government a “necessary evil” and kings “crowned ruffians” expresses skepticism of power and of hereditary rule.', w: ['The opposite.', 'Correct.', 'The excerpt doesn’t address economics.', 'Paine’s argument isn’t theocratic.'] },
{ id: 'm0304', l: 'l03', d: 'm', sk: 'compare', q: 'The first state constitutions written after 1776 generally', o: ['created powerful governors and weak legislatures', 'gave most power to elected legislatures and limited the power of governors', 'abolished all property requirements for voting', 'banned slavery in every state'], a: 1, x: 'Fear of executive tyranny, based on royal governors and the king, led to strong legislatures and weak executives.', w: ['The reverse.', 'Correct.', 'Most kept property or taxpaying requirements.', 'Only some Northern states moved against slavery.'] },
{ id: 'm0305', l: 'l03', d: 'm', sk: 'ccot', q: 'Pennsylvania’s 1780 law providing for gradual emancipation is best understood as', o: ['an immediate end to slavery in the state', 'an example of revolutionary ideals prompting some Northern states to begin ending slavery', 'a federal law applying to all states', 'a response to the Missouri Compromise'], a: 1, x: 'Children born to enslaved mothers after 1780 would be freed at 28, a slow process inspired by revolutionary rhetoric.', w: ['It was gradual.', 'Correct.', 'It was a state law.', 'That came 40 years later.'] },
{ id: 'm0306', l: 'l03', d: 'h', sk: 'source', s: 'remladies', q: 'Abigail Adams’s letter is best used as evidence of', o: ['widespread support among founders for women’s suffrage', 'tension between revolutionary ideals of liberty and the limited rights of women', 'the Continental Congress’s plan to grant women property rights', 'women’s opposition to American independence'], a: 1, x: 'She applies the Revolution’s language of tyranny and unlimited power to husbands, which exposes a contradiction.', w: ['Most founders, including John Adams, dismissed her request.', 'Correct.', 'No such plan existed.', 'She eagerly hoped for independence.'] },
{ id: 'm0307', l: 'l03', d: 'h', sk: 'compare', q: 'Compared to Pennsylvania’s 1776 constitution, Massachusetts’s 1780 constitution', o: ['created a unicameral legislature with no governor', 'established a bicameral legislature, a strong governor and separate branches', 'eliminated all voting requirements', 'was imposed by the Continental Congress'], a: 1, x: 'Pennsylvania’s was the most democratic (unicameral, no governor); Massachusetts’s (John Adams) was balanced and later influenced the U.S. Constitution.', w: ['That describes Pennsylvania.', 'Correct.', 'It kept property requirements.', 'It was ratified by a special convention and a popular vote.'] },
{ id: 'm0308', l: 'l03', d: 'h', sk: 'claim', q: 'Which development would best support the argument that revolutionary ideals expanded political participation in the 1770s–1780s?', o: ['New Jersey’s 1776 constitution allowing some property-owning women and free Black men to vote', 'Southern states keeping high property requirements for officeholding', 'The removal of the slave-trade passage from the Declaration', 'The Proclamation of 1763'], a: 0, x: 'New Jersey briefly opened the vote to all “inhabitants” meeting a property threshold. It was a real (if temporary) expansion.', w: ['Correct.', 'That limited participation.', 'That shows ideals being compromised.', 'A British policy, before the Revolution.'] },
{ id: 'm0309', l: 'l03', d: 'c', sk: 'ccot', q: 'Which of the following later movements most directly used the language of the Declaration of Independence to challenge a contradiction similar to the one Abigail Adams raised in 1776?', o: ['The Seneca Falls Convention’s Declaration of Sentiments (1848)', 'The Hartford Convention (1814)', 'The Kansas-Nebraska Act (1854)', 'The Pendleton Civil Service Act (1883)'], a: 0, x: 'Seneca Falls rewrote the Declaration (“all men and women are created equal”) to demand women’s rights.', w: ['Correct.', 'A Federalist protest against the War of 1812.', 'A law about slavery in territories.', 'A civil-service reform law.'] },

/* ── L4 Articles ── */
{ id: 'm0401', l: 'l04', d: 'e', sk: 'context', q: 'Under the Articles of Confederation, the national government could NOT', o: ['make treaties', 'levy taxes directly on citizens', 'declare war', 'manage relations with Native nations'], a: 1, x: 'Congress could only request (requisition) money from states, which often didn’t pay.', w: ['Congress could make treaties (e.g., Paris 1783).', 'Correct.', 'Congress could declare war.', 'Congress did handle Native relations.'] },
{ id: 'm0402', l: 'l04', d: 'e', sk: 'cause', q: 'The framers of the Articles of Confederation created a weak central government mainly because', o: ['they feared a powerful central authority like the British government they had rebelled against', 'Britain required it in the Treaty of Paris', 'the states had no experience with self-government', 'they wanted the president to hold most of the power'], a: 0, x: 'After fighting “tyranny,” Americans distrusted concentrated power.', w: ['Correct.', 'Britain imposed no such terms.', 'States had long self-government experience.', 'There was no president under the Articles.'] },
{ id: 'm0403', l: 'l04', d: 'm', sk: 'claim', q: 'Which was the most significant ACCOMPLISHMENT of the government under the Articles of Confederation?', o: ['Creating a strong national currency', 'Establishing a process for admitting new states through the Northwest Ordinance', 'Ending Shays’ Rebellion with a national army', 'Regulating trade between the states'], a: 1, x: 'The Northwest Ordinance set up equal statehood and banned slavery north of the Ohio River.', w: ['Continental currency became nearly worthless.', 'Correct.', 'There was no national army to send.', 'Congress had no power over interstate trade.'] },
{ id: 'm0404', l: 'l04', d: 'm', sk: 'source', s: 'washshays', q: 'Washington’s letter most directly expresses concern that', o: ['Britain was secretly supporting American rebels', 'the governments under the Articles lacked the strength to maintain order', 'the states had too much power over trade with Britain', 'farmers deserved relief from their debts'], a: 1, x: '“The want of energy in our governments” means a lack of strength: the core critique of the Articles.', w: ['He uses “tory” and “Briton” rhetorically, not as a literal accusation.', 'Correct.', 'He doesn’t mention trade.', 'He doesn’t sympathize with the rebels here.'] },
{ id: 'm0405', l: 'l04', d: 'm', sk: 'cause', s: 'washshays', q: 'The disorders described in the excerpt most directly contributed to', o: ['the calling of the Constitutional Convention in 1787', 'the outbreak of the War of 1812', 'the passage of the Alien and Sedition Acts', 'the end of salutary neglect'], a: 0, x: 'Shays’ Rebellion alarmed elites and ensured the Philadelphia convention would meet with strong support.', w: ['Correct.', 'That was decades later and had different causes.', 'Those came in 1798, during tensions with France.', 'Salutary neglect ended in 1763.'] },
{ id: 'm0406', l: 'l04', d: 'h', sk: 'cause', q: 'Maryland delayed ratifying the Articles of Confederation until 1781 because', o: ['it opposed the equal vote of each state in Congress', 'it wanted states with large western land claims to give them to the national government', 'it demanded a national bank', 'it insisted on a bill of rights'], a: 1, x: 'Landless Maryland feared Virginia and other states with huge western claims; they ceded them, creating a national domain.', w: ['Small states liked equal votes.', 'Correct.', 'A national bank wasn’t at issue.', 'That was a Constitution-era demand.'] },
{ id: 'm0407', l: 'l04', d: 'h', sk: 'compare', q: 'The Critical Period problem that most closely resembled a grievance colonists had against Britain was', o: ['states taxing each other’s goods', 'farmers facing taxes and court actions they believed unjust, imposed by a distant government', 'Spain closing the Mississippi River', 'Congress’s inability to pay soldiers'], a: 1, x: 'Shays’ rebels saw Boston’s taxes and courts the way colonists had seen Parliament’s, as unjust burdens from distant elites.', w: ['Interstate trade wars had no colonial parallel.', 'Correct.', 'A foreign-policy problem.', 'A financial weakness, not a parallel grievance.'] },
{ id: 'm0408', l: 'l04', d: 'h', sk: 'ccot', q: 'The Northwest Ordinance’s ban on slavery north of the Ohio River set a precedent that was later', o: ['followed in the Missouri Compromise’s 36°30′ line', 'overturned by the Compromise of 1850', 'adopted as the 13th Amendment', 'endorsed by the Dred Scott decision'], a: 0, x: 'Congress banning slavery in federal territory carried forward in 1820, until Dred Scott said Congress lacked that power.', w: ['Correct.', 'The 1850 compromise didn’t address the Northwest.', 'The 13th Amendment abolished slavery everywhere.', 'Dred Scott rejected Congress’s power to ban slavery in territories.'] },
{ id: 'm0409', l: 'l04', d: 'c', sk: 'compare', q: 'Which statement best compares the national government’s responses to Shays’ Rebellion (1786–87) and the Whiskey Rebellion (1794)?', o: ['Both rebellions were crushed by federal troops', 'The first exposed the national government’s inability to keep order; the second showed the new federal government could enforce its laws', 'Both rebellions led directly to the creation of the Bill of Rights', 'Neither rebellion produced any change in national policy'], a: 1, x: 'In 1787 Massachusetts relied on a privately funded militia; in 1794 Washington led about 13,000 federal troops.', w: ['No federal force existed in 1787.', 'Correct.', 'Neither produced the Bill of Rights.', 'Shays’ helped spark a new constitution.'] },

/* ── L5 Constitution ── */
{ id: 'm0501', l: 'l05', d: 'e', sk: 'compare', q: 'The Great Compromise resolved the dispute over', o: ['how to count enslaved people', 'whether representation in Congress should be based on population or equal for each state', 'how to elect the president', 'whether to include a bill of rights'], a: 1, x: 'It created a population-based House and an equal Senate.', w: ['That was the Three-Fifths Compromise.', 'Correct.', 'That was the Electoral College.', 'Delegates left out a bill of rights.'] },
{ id: 'm0502', l: 'l05', d: 'e', sk: 'context', q: 'The power of the president to veto bills passed by Congress is an example of', o: ['federalism', 'checks and balances', 'popular sovereignty', 'judicial review'], a: 1, x: 'One branch limiting another.', w: ['Federalism divides national and state power.', 'Correct.', 'The idea that power comes from the people.', 'The courts’ power to strike down laws.'] },
{ id: 'm0503', l: 'l05', d: 'm', sk: 'source', s: 'threefifths', q: 'The provision in the excerpt had which effect in the early republic?', o: ['It reduced the South’s representation in Congress', 'It increased the representation of slaveholding states in the House and Electoral College', 'It gave enslaved people limited voting rights', 'It required Northern states to pay higher taxes'], a: 1, x: 'Counting three-fifths of enslaved people added seats and electoral votes to slave states.', w: ['The opposite. Southern representation rose.', 'Correct.', 'Enslaved people had no vote.', 'Direct taxes were apportioned the same way and rarely levied.'] },
{ id: 'm0504', l: 'l05', d: 'm', sk: 'context', s: 'threefifths', q: 'The phrase “all other Persons” in the excerpt reflects which feature of the Constitution?', o: ['Its guarantee of equal rights to all inhabitants', 'Its avoidance of the word “slavery” while protecting the institution', 'Its inclusion of Native Americans as citizens', 'Its plan to end slavery in 1808'], a: 1, x: 'The framers never wrote “slave” or “slavery,” using euphemisms while protecting slavery.', w: ['The clause treated enslaved people as partial persons for others’ benefit.', 'Correct.', '“Indians not taxed” are excluded.', '1808 concerned the slave TRADE, not slavery.'] },
{ id: 'm0505', l: 'l05', d: 'm', sk: 'context', q: 'Under the original Constitution, U.S. senators were chosen by', o: ['direct popular vote', 'state legislatures', 'the Electoral College', 'the House of Representatives'], a: 1, x: 'Direct election came with the 17th Amendment (1913).', w: ['Only the House was directly elected.', 'Correct.', 'The Electoral College chooses the president.', 'The House picks the president only if no one has an electoral majority.'] },
{ id: 'm0506', l: 'l05', d: 'h', sk: 'cause', q: 'The framers created the Electoral College and indirect election of senators primarily because they', o: ['wanted to give all adult men an equal voice', 'feared that direct popular majorities might act rashly or threaten minority rights', 'believed the states should have no role in national elections', 'wanted to copy the British system of choosing a monarch'], a: 1, x: 'Concern about “tyranny of the majority” led to filters between the people and power.', w: ['Indirect election limits the direct voice of the people.', 'Correct.', 'States play a big role in both mechanisms.', 'They rejected monarchy.'] },
{ id: 'm0507', l: 'l05', d: 'h', sk: 'compare', q: 'Which change from the Articles of Confederation to the Constitution most directly addressed interstate trade wars?', o: ['Creating a national court system', 'Giving Congress power to regulate interstate and foreign commerce', 'Requiring unanimous consent for amendments', 'Creating a two-house legislature'], a: 1, x: 'The Commerce Clause let Congress stop states from taxing each other’s goods.', w: ['Courts help, but the core fix was Congress’s commerce power.', 'Correct.', 'The Constitution REMOVED the unanimity requirement.', 'That resolved representation, not trade.'] },
{ id: 'm0508', l: 'l05', d: 'h', sk: 'claim', q: 'Which provision of the Constitution best supports the argument that the document protected slavery?', o: ['The Commerce Clause', 'The Fugitive Slave Clause of Article IV', 'The Necessary and Proper Clause', 'The guarantee of a republican form of government to each state'], a: 1, x: 'It required escaped enslaved people to be returned, even from free states.', w: ['Not specifically about slavery.', 'Correct.', 'A general grant of implied power.', 'Not specifically about slavery.'] },
{ id: 'm0509', l: 'l05', d: 'm', sk: 'context', q: 'Which of the following is a power RESERVED to the states?', o: ['Coining money', 'Running elections and setting voter qualifications', 'Declaring war', 'Making treaties'], a: 1, x: 'The original Constitution left voter qualifications to the states. That’s why voting rights expanded state by state.', w: ['Federal power.', 'Correct.', 'Federal power.', 'Federal power.'] },
{ id: 'm0510', l: 'l05', d: 'c', sk: 'ccot', q: 'The Constitution’s compromise allowing the slave trade until 1808 is best seen as part of a broader pattern in which', o: ['national leaders repeatedly postponed confronting slavery in order to preserve the Union', 'the federal government steadily expanded slavery through the 1800s', 'Northern states refused any compromise on slavery', 'slavery was treated as a purely state issue that never reached national politics'], a: 0, x: 'From 1787 through 1820 and 1850, compromise kept the Union together by putting off a final reckoning, until 1860.', w: ['Correct.', 'Congress banned the slave trade in 1808 and restricted slavery at times.', 'Northern delegates repeatedly compromised.', 'Slavery repeatedly reached national politics.'] },

/* ── L6 Ratification ── */
{ id: 'm0601', l: 'l06', d: 'e', sk: 'compare', q: 'Anti-Federalists opposed ratification of the Constitution mainly because they believed', o: ['the national government would be too weak to keep order', 'a strong central government without a bill of rights could threaten individual liberty', 'the Articles of Confederation gave too much power to Congress', 'the Constitution banned slavery'], a: 1, x: 'They feared a new tyranny and demanded protections for rights.', w: ['That was the Federalist critique of the ARTICLES.', 'Correct.', 'The Articles were weak.', 'It didn’t ban slavery.'] },
{ id: 'm0602', l: 'l06', d: 'e', sk: 'cause', q: 'The Bill of Rights was added to the Constitution primarily to', o: ['win over Anti-Federalists who feared the new government', 'give the federal government power to tax', 'end the slave trade', 'strengthen the presidency'], a: 0, x: 'Federalists promised amendments to secure ratification in key states.', w: ['Correct.', 'Taxing power was already in Article I.', 'Not part of the Bill of Rights.', 'It limits government power.'] },
{ id: 'm0603', l: 'l06', d: 'm', sk: 'source', s: 'fed10', q: 'Madison’s argument in the excerpt is that a large republic', o: ['would be impossible to govern effectively', 'would make it harder for any single faction to form an oppressive majority', 'should be divided into smaller independent nations', 'requires a monarch to keep order'], a: 1, x: 'More interests means less chance that one majority unites to oppress others.', w: ['That’s the Anti-Federalist view (see Brutus).', 'Correct.', 'He argues for one extended republic.', 'Madison supported republican government.'] },
{ id: 'm0604', l: 'l06', d: 'm', sk: 'compare', s: 'brutus', q: 'The author of this excerpt would most likely have disagreed with Madison about', o: ['whether a republic could work over a large territory', 'whether the Articles of Confederation had weaknesses', 'whether British rule had been tyrannical', 'whether elected representatives should make laws'], a: 0, x: 'Brutus argued a free republic “cannot succeed” over so large a country; Madison argued size was an advantage.', w: ['Correct.', 'Many Anti-Federalists admitted the Articles needed fixing.', 'Both opposed British tyranny.', 'Both supported representative government.'] },
{ id: 'm0605', l: 'l06', d: 'm', sk: 'context', s: 'brutus', q: 'Which group would have been MOST likely to agree with the excerpt?', o: ['Merchants in coastal cities', 'Small farmers in rural and western areas', 'Bankers and creditors', 'Supporters of Hamilton’s financial plan'], a: 1, x: 'Anti-Federalist strength lay with rural farmers who distrusted distant elites.', w: ['Merchants generally supported the Constitution.', 'Correct.', 'Creditors wanted strong government to protect contracts.', 'Hamiltonians wanted strong national power.'] },
{ id: 'm0606', l: 'l06', d: 'h', sk: 'context', q: 'Anti-Federalists objected to the Necessary and Proper Clause mainly because they feared it would', o: ['prevent Congress from collecting taxes', 'allow Congress to expand its powers far beyond those listed', 'require states to abolish slavery', 'give the Supreme Court power over the president'], a: 1, x: 'The “elastic” wording could stretch federal power without limit, which is why it was a key Anti-Federalist fear.', w: ['Congress’s taxing power was separate.', 'Correct.', 'Unrelated.', 'Unrelated.'] },
{ id: 'm0607', l: 'l06', d: 'h', sk: 'cause', q: 'The 10th Amendment was most directly intended to', o: ['protect freedom of speech and the press', 'reassure Americans that powers not delegated to the national government remained with the states or the people', 'establish judicial review', 'allow states to secede'], a: 1, x: 'It answered the Anti-Federalist fear of unlimited federal power.', w: ['That’s the 1st Amendment.', 'Correct.', 'Judicial review came from Marbury (1803).', 'It says nothing about secession.'] },
{ id: 'm0608', l: 'l06', d: 'h', sk: 'claim', q: 'Which of the following best supports the claim that the Anti-Federalists influenced the Constitution despite losing the ratification debate?', o: ['The Three-Fifths Compromise', 'The adoption of the Bill of Rights in 1791', 'The creation of the Electoral College', 'The Supremacy Clause'], a: 1, x: 'Their central demand became the first ten amendments.', w: ['Decided at the Convention before ratification.', 'Correct.', 'Decided at the Convention.', 'Anti-Federalists opposed it.'] },
{ id: 'm0609', l: 'l06', d: 'c', sk: 'ccot', q: 'The Federalist–Anti-Federalist disagreement over the scope of national power most directly continued in which later debate?', o: ['Hamilton and Jefferson’s dispute over a national bank', 'The debate over the Proclamation of 1763', 'The argument over the Olive Branch Petition', 'The dispute over the Albany Plan of Union'], a: 0, x: 'Loose vs. strict construction of the elastic clause was the same question, and it created the first parties.', w: ['Correct.', 'A British policy before the Constitution existed.', 'A colonial petition to the king.', 'A 1754 proposal.'] },

/* ── L7 1790s ── */
{ id: 'm0701', l: 'l07', d: 'e', sk: 'compare', q: 'Which group was MOST likely to support the Federalist Party in the 1790s?', o: ['Kentucky farmers', 'New England merchants', 'Virginia planters', 'Recent Irish immigrants'], a: 1, x: 'Federalists drew support from commercial, urban and Northeastern interests.', w: ['Western farmers backed Jefferson.', 'Correct.', 'Southern planters backed Jefferson.', 'Immigrants leaned Democratic-Republican, especially after the Alien Acts.'] },
{ id: 'm0702', l: 'l07', d: 'e', sk: 'context', q: 'Jefferson opposed Hamilton’s national bank chiefly because he believed it', o: ['would make the U.S. dependent on France', 'was not authorized by the Constitution', 'would lower tariffs too much', 'would end slavery'], a: 1, x: 'As a strict constructionist, Jefferson said the Constitution didn’t list bank-chartering as a power.', w: ['Unrelated.', 'Correct.', 'Unrelated.', 'Unrelated.'] },
{ id: 'm0703', l: 'l07', d: 'm', sk: 'source', s: 'farewell', q: 'Washington’s warning in the excerpt was most directly a response to', o: ['the growing rivalry between Federalists and Democratic-Republicans', 'Shays’ Rebellion', 'the Missouri Compromise', 'the rise of the Whig Party'], a: 0, x: 'By 1796 the first parties had formed over Hamilton’s program and foreign policy.', w: ['Correct.', 'That was in 1786, before parties existed.', 'That was in 1820.', 'The Whigs formed in the 1830s.'] },
{ id: 'm0704', l: 'l07', d: 'm', sk: 'context', s: 'farewell', q: 'The advice to “steer clear of permanent alliances” reflected Washington’s concern about', o: ['being drawn into conflicts between Britain and France', 'Spanish control of Florida', 'Native American alliances with the Dutch', 'Mexican claims to Texas'], a: 0, x: 'The French Revolutionary wars split Americans and threatened to drag the U.S. in.', w: ['Correct.', 'Not the main 1790s concern.', 'Not a real issue in 1796.', 'Texas was a much later issue.'] },
{ id: 'm0705', l: 'l07', d: 'm', sk: 'cause', q: 'Washington’s forceful response to the Whiskey Rebellion demonstrated that', o: ['the new federal government could enforce its laws', 'the states retained the power to nullify federal taxes', 'Hamilton’s financial plan had failed', 'western farmers supported the Federalists'], a: 0, x: 'About 13,000 troops quickly ended the revolt. The contrast with Shays’ Rebellion is the point.', w: ['Correct.', 'The opposite.', 'The tax was enforced.', 'Many westerners turned to Jefferson after it.'] },
{ id: 'm0706', l: 'l07', d: 'h', sk: 'cause', q: 'The Alien and Sedition Acts most directly prompted', o: ['the Virginia and Kentucky Resolutions', 'the Hartford Convention', 'the XYZ Affair', 'the Whiskey Rebellion'], a: 0, x: 'Jefferson and Madison argued states could judge federal laws unconstitutional.', w: ['Correct.', 'The Hartford Convention (1814) responded to the War of 1812.', 'The XYZ Affair came BEFORE the Acts and helped cause them.', '1794, before the Acts.'] },
{ id: 'm0707', l: 'l07', d: 'h', sk: 'cause', q: 'Which of the following was a major reason Federalists passed the Alien and Sedition Acts?', o: ['To weaken the Democratic-Republicans, whose supporters included many immigrants and critical newspaper editors', 'To prepare for war with Britain', 'To fund Hamilton’s national bank', 'To end the Quasi-War by appeasing France'], a: 0, x: 'Amid war fever with France, Federalists targeted their political opponents.', w: ['Correct.', 'The tension was with France.', 'Unrelated to the bank.', 'The Acts reflected hostility to France.'] },
{ id: 'm0708', l: 'l07', d: 'h', sk: 'compare', q: 'Federalists and Democratic-Republicans in the 1790s differed most sharply over', o: ['whether to keep the Constitution', 'the proper scope of federal power and whether to favor Britain or France', 'whether to end slavery immediately', 'whether to expand voting rights to women'], a: 1, x: 'Constitutional interpretation, economic policy and foreign policy divided them.', w: ['Both worked within the Constitution.', 'Correct.', 'Neither party pursued immediate abolition.', 'Neither party supported this.'] },
{ id: 'm0709', l: 'l07', d: 'm', sk: 'context', q: 'The election of 1800 is called the “Revolution of 1800” because', o: ['it was decided by armed conflict', 'power passed peacefully from one party to its rival', 'it was the first election with universal male suffrage', 'it ended the Electoral College'], a: 1, x: 'Adams (Federalist) peacefully handed power to Jefferson (Democratic-Republican).', w: ['It was peaceful.', 'Correct.', 'Universal white male suffrage came decades later.', 'The 12th Amendment adjusted it but didn’t end it.'] },
{ id: 'm0710', l: 'l07', d: 'c', sk: 'ccot', q: 'The ideas expressed in the Virginia and Kentucky Resolutions were most directly revived during the', o: ['Nullification Crisis of 1832', 'XYZ Affair', 'Louisiana Purchase debate', 'Whiskey Rebellion'], a: 0, x: 'South Carolina claimed it could nullify the federal tariff, the Kentucky Resolution’s idea taken further.', w: ['Correct.', 'Came before the Resolutions.', 'The Purchase didn’t involve state nullification.', 'Came before the Resolutions.'] },

/* ── L8 Marshall Court ── */
{ id: 'm0801', l: 'l08', d: 'e', sk: 'context', q: 'Marbury v. Madison (1803) established the principle of', o: ['judicial review', 'implied powers', 'popular sovereignty', 'nullification'], a: 0, x: 'The Court’s power to declare laws unconstitutional.', w: ['Correct.', 'Implied powers came from McCulloch (1819).', 'Unrelated.', 'A states’-rights theory the Court never endorsed.'] },
{ id: 'm0802', l: 'l08', d: 'e', sk: 'cause', q: 'The Federalist Party declined rapidly after 1815 largely because', o: ['its opposition to the War of 1812 and the Hartford Convention made it appear disloyal', 'it supported the Louisiana Purchase', 'John Marshall left the party', 'it merged with the Whigs'], a: 0, x: 'The Hartford Convention met just as news of victory and peace arrived.', w: ['Correct.', 'Federalists largely opposed the Purchase.', 'Marshall stayed on the Court.', 'The Whigs didn’t exist until the 1830s.'] },
{ id: 'm0803', l: 'l08', d: 'm', sk: 'source', s: 'mcculloch', q: 'Marshall’s reasoning in the excerpt most closely resembles the earlier argument of', o: ['Thomas Jefferson against the national bank', 'Alexander Hamilton in favor of the national bank', 'the Anti-Federalists against the Constitution', 'the Kentucky Resolutions'], a: 1, x: 'Any appropriate means to a legitimate end is constitutional. That is loose construction and implied powers.', w: ['Jefferson argued the opposite.', 'Correct.', 'Anti-Federalists feared exactly this reading.', 'States’-rights reasoning.'] },
{ id: 'm0804', l: 'l08', d: 'm', sk: 'cause', s: 'mcculloch', q: 'The ruling from which this excerpt is taken had the effect of', o: ['limiting Congress to its enumerated powers', 'strengthening federal authority over the states', 'allowing states to tax federal institutions', 'ending the Second Bank of the United States'], a: 1, x: 'McCulloch upheld implied powers and forbade states from taxing the Bank.', w: ['The opposite.', 'Correct.', 'The opposite: states could not tax the Bank.', 'Jackson killed the Bank later.'] },
{ id: 'm0805', l: 'l08', d: 'm', sk: 'context', s: 'marbury', q: 'The excerpt is significant because it', o: ['asserted the Supreme Court’s power to decide when a law conflicts with the Constitution', 'created the federal court system', 'gave states the final say over constitutionality', 'established the president’s power to appoint judges'], a: 0, x: 'This is the heart of judicial review.', w: ['Correct.', 'Congress created lower courts in 1789.', 'It gives the federal judiciary that role.', 'That’s in Article II.'] },
{ id: 'm0806', l: 'l08', d: 'h', sk: 'claim', q: 'Which action by Thomas Jefferson most clearly contradicted his strict constructionist principles?', o: ['Repealing the whiskey tax', 'Reducing the size of the army and navy', 'Purchasing the Louisiana Territory', 'Paying down the national debt'], a: 2, x: 'The Constitution didn’t mention acquiring territory, yet Jefferson bought it.', w: ['Consistent with limited government.', 'Consistent with limited government.', 'Correct.', 'Consistent with his goals.'] },
{ id: 'm0807', l: 'l08', d: 'h', sk: 'context', q: 'Gibbons v. Ogden (1824) is best described as a decision that', o: ['broadly defined Congress’s power to regulate interstate commerce', 'protected state monopolies on navigation', 'struck down the Second Bank of the United States', 'limited the power of the Supreme Court'], a: 0, x: 'Commerce includes navigation; federal power overrode New York’s steamboat monopoly.', w: ['Correct.', 'It struck down the monopoly.', 'McCulloch upheld the Bank.', 'It strengthened federal power.'] },
{ id: 'm0808', l: 'l08', d: 'h', sk: 'compare', q: 'Which statement best describes a similarity among Marbury v. Madison, McCulloch v. Maryland and Gibbons v. Ogden?', o: ['Each limited federal power in favor of the states', 'Each strengthened the federal government or the federal judiciary', 'Each concerned the expansion of slavery', 'Each was decided after John Marshall left the Court'], a: 1, x: 'All three were Marshall Court rulings that built national power.', w: ['The opposite.', 'Correct.', 'None concerned slavery.', 'Marshall wrote all three.'] },
{ id: 'm0809', l: 'l08', d: 'c', sk: 'ccot', q: 'The interpretation of the Commerce Clause in Gibbons v. Ogden was later used to justify which development?', o: ['The Dred Scott decision', 'Title II of the Civil Rights Act of 1964 banning discrimination in public accommodations', 'The Compromise of 1877', 'The Kentucky Resolutions'], a: 1, x: 'Congress justified banning segregation in hotels and restaurants as a regulation of interstate commerce.', w: ['Dred Scott limited federal power over slavery.', 'Correct.', 'A political deal, not commerce law.', 'States’-rights resolutions from 1798–99.'] }

);
